function Sharing:Roster()
    local result = {}
    if not Enabled() then return result end
    for index = 1, 4 do
        local name = names.UnitName("party" .. index)
        local key = name and names.PlayerKey(name)
        if key and key ~= LocalKey() then result[key] = name end
    end
    return result
end--[[APR_DIAG]]; Sharing.Roster = APRTrace("APR-Core/features/group/PathSharing.lua:27:Sharing:Roster#4", Sharing.Roster)--[[/APR_DIAG]]

