function Sharing:Sweep()
    local roster, now = self:Roster(), GetTime()
    for _, pool in ipairs({ self.incoming, self.outgoing }) do
        for id, request in pairs(pool) do
            if not roster[request.peer] or request.profile ~= APR:GetSettingsProfile()
                or now - request.started > P.TTL or now - request.touched > P.IDLE_TTL then
                pool[id] = nil
                if self.prompt == request then self.prompt = nil; self:CloseDialog() end
                self:Status("GROUP_PATH_SHARE_EXPIRED")
            end
        end
    end
    for key in pairs(self.peers) do if not roster[key] then self.peers[key] = nil end end
    for _, cache in ipairs({ self.lastOffer or {}, self.helloReplies or {} }) do
        for key in pairs(cache) do if not roster[key] then cache[key] = nil end end
    end
    if next(self.incoming) or next(self.outgoing) then self:ArmSweep() end
    self:ShowNext()
end--[[APR_DIAG]]; Sharing.Sweep = APRTrace("APR-Core/features/group/PathSharing.lua:87:Sharing:Sweep#15", Sharing.Sweep)--[[/APR_DIAG]]

local function Fingerprint(definition)
    if not APR.PartyFinderProtocol or not definition then return end
    local job = APR.PartyFinderProtocol.NewFingerprintJob(definition)
    while not job.done do job:Step(4096) end
    return job.digest
end--[[APR_DIAG]]; Fingerprint = APRTrace("APR-Core/features/group/PathSharing.lua:107:Fingerprint#16", Fingerprint)--[[/APR_DIAG]]

