        local context = APR:CaptureStepContext()
        local progress = APR:GetGroupRouteProgress(context.route, context.index)
        local fingerprint = progress and Fingerprint(APR:GetRouteData(context.route))
        if visited[context.route] and progress and fingerprint then
            packet.position = { route = context.route, id = progress.id, fingerprint = fingerprint }
        end
