    if not P.Packet(packet) then return end
    local ok, wire = --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](serializer.Serialize, serializer, packet)
