function Sharing:Offer(kind, routeKey, target)
    if not Enabled() or InCombatLockdown() then return false end
    local roster, destinations = self:Roster(), {}
    if target then
        local key = names.PlayerKey(target)
        if key and roster[key] and self.peers[key] then destinations[1] = key end
    else
        for key in pairs(roster) do if self.peers[key] then destinations[#destinations + 1] = key end end
    end
    if #destinations == 0 then self:Status("GROUP_PATH_SHARE_NO_PEERS"); return false end
    if next(self.outgoing) then self:Status("GROUP_PATH_SHARE_BUSY"); return false end
    local packet, wire = self:BuildPacket(kind, routeKey)
    if not packet then self:Status("GROUP_PATH_SHARE_INVALID"); return false end
    for _, peer in ipairs(destinations) do
        serial = serial + 1
        local id = tostring(math.random(10000, 99999)) .. "-" .. serial
        local request = { id = id, peer = peer, packet = packet, wire = wire,
            started = GetTime(), touched = GetTime(), profile = APR:GetSettingsProfile() }
        self.outgoing[id] = request
        self:Send("O|" .. id .. "|" .. peer .. "|" .. kind .. "|" .. #wire)
    end
    self:ArmSweep()
    self:Status("GROUP_PATH_SHARE_SENT")
    return true
end--[[APR_DIAG]]; Sharing.Offer = APRTrace("APR-Core/features/group/PathSharing.lua:161:Sharing:Offer#21", Sharing.Offer)--[[/APR_DIAG]]

function Sharing:RequestCurrent(request)
    return self.incoming[request.id] == request and Enabled() and self:Roster()[request.peer]
        and request.profile == APR:GetSettingsProfile() and request.player == APR.PlayerID
        and GetTime() - request.started <= P.TTL and GetTime() - request.touched <= P.IDLE_TTL
end--[[APR_DIAG]]; Sharing.RequestCurrent = APRTrace("APR-Core/features/group/PathSharing.lua:187:Sharing:RequestCurrent#22", Sharing.RequestCurrent)--[[/APR_DIAG]]

