function Sharing:Decline(request)
    if self.incoming[request.id] ~= request then return end
    self:Send("X|" .. request.id)
    self.incoming[request.id] = nil
    if self.prompt == request then self.prompt = nil; self:CloseDialog() end
    -- A shared dialog can call its old cancellation handler while replacing
    -- itself. Wait until that replacement has finished before considering peers.
    C_Timer.After(0, ResumePrompts)
end--[[APR_DIAG]]; Sharing.Decline = APRTrace("APR-Core/features/group/PathSharing.lua:195:Sharing:Decline#24", Sharing.Decline)--[[/APR_DIAG]]

