function Sharing:ReceiveData(sender, id, index, total, data)
    local request = self.incoming[id]
    if not request or request.peer ~= sender or request.state ~= "receiving" or not self:RequestCurrent(request) then return end
    if not P.Integer(index, 1, math.ceil(P.MAX_BYTES / P.CHUNK))
        or total ~= math.ceil(request.size / P.CHUNK) or index > total
        or #data ~= (index == total and (request.size - (total - 1) * P.CHUNK) or P.CHUNK) then
        self:Decline(request); return
    end
    if request.parts[index] then
        if request.parts[index] ~= data then self:Decline(request) end
        return
    end
    request.parts[index], request.count = data, request.count + 1
    request.bytes, request.touched = request.bytes + #data, GetTime()
    local percent = math.floor(100 * request.bytes / request.size)
    if math.floor(percent / 10) ~= request.percent then
        request.percent = math.floor(percent / 10)
        if self.prompt == request and self.dialog and self.dialog.dialogGeneration == self.dialogGeneration then
            self.dialog.description:SetText(string.format(L["GROUP_PATH_SHARE_PROGRESS"], percent .. "%"))
        end
    end
    if request.count ~= total then return end
    local wire = table.concat(request.parts)
    request.parts = nil
    local ok, decoded, packet = --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](serializer.Deserialize, serializer, wire)
    if not ok or not decoded or not P.Packet(packet) or packet.kind ~= request.kind
        or packet.client ~= APR:GetGameVersion() then
        self:Status("GROUP_PATH_SHARE_INVALID"); self:Decline(request); return
    end
    request.packet, request.state = packet, "ready"
    if self.prompt == request then self.prompt = nil; self:CloseDialog() end
    self:ShowNext()
end--[[APR_DIAG]]; Sharing.ReceiveData = APRTrace("APR-Core/features/group/PathSharing.lua:243:Sharing:ReceiveData#31", Sharing.ReceiveData)--[[/APR_DIAG]]

function Sharing:OnAddonMessage(_, prefix, message, channel, sender)
    if prefix ~= P.PREFIX or not Enabled() or channel ~= Channel() or type(message) ~= "string" or #message > 255 then return end
    local peer = names.PlayerKey(sender)
    local roster = self:Roster()
    if not peer or not roster[peer] then return end
    if message == "H|1" or message == "h|1" then
        self.peers[peer] = true
        self.helloReplies = self.helloReplies or {}
        if message == "H|1" and GetTime() - (self.helloReplies[peer] or -100) >= 5 then
            self.helloReplies[peer] = GetTime()
            self:Send("h|1")
        end
        return
    end
    local kind, id, rest = message:match("^(%u)|([%w%-]+)|?(.*)$")
    if not id or #id > 24 then return end
    if kind == "O" then
        local target, mode, size = rest:match("^([^|]+)|(%a+)|(%d+)$")
        size = tonumber(size)
        if target ~= LocalKey() or not self.peers[peer] or (mode ~= "path" and mode ~= "route")
            or not P.Integer(size, 1, P.MAX_BYTES) or self.incoming[id] then return end
        for _, pending in pairs(self.incoming) do if pending.peer == peer then return end end
        local now = GetTime()
        if self.lastOffer and now - (self.lastOffer[peer] or -100) < 10 then return end
        self.lastOffer = self.lastOffer or {}; self.lastOffer[peer] = now
        self.incoming[id] = { id = id, peer = peer, name = roster[peer], kind = mode, size = size,
            started = now, touched = now, state = "offered", profile = APR:GetSettingsProfile(), player = APR.PlayerID }
        self:ArmSweep(); self:ShowNext()
    elseif kind == "D" then
        local index, total, data = rest:match("^(%d+)|(%d+)|(.*)$")
        if data then self:ReceiveData(peer, id, tonumber(index), tonumber(total), data) end
    elseif kind == "R" or kind == "X" or kind == "A" then
        if kind == "X" then
            local incoming = self.incoming[id]
            if incoming and incoming.peer == peer then
                self:Decline(incoming)
                return
            end
        end
        local request = self.outgoing[id]
        if not request or request.peer ~= peer then return end
        if kind == "R" and not request.index then request.index = 1; self:Pump(request)
        elseif kind ~= "R" then
            self.outgoing[id] = nil
            self:Status(kind == "A" and "GROUP_PATH_SHARE_ACCEPTED" or "GROUP_PATH_SHARE_DECLINED", roster[peer])
        end
    end
end--[[APR_DIAG]]; Sharing.OnAddonMessage = APRTrace("APR-Core/features/group/PathSharing.lua:277:Sharing:OnAddonMessage#32", Sharing.OnAddonMessage)--[[/APR_DIAG]]

function Sharing:RefreshRoster()
