end--[[APR_DIAG]]; Sharing.RefreshRoster = APRTrace("APR-Core/features/group/PathSharing.lua:326:Sharing:RefreshRoster#33", Sharing.RefreshRoster)--[[/APR_DIAG]]

function Sharing:OnEnable()
    if not C_ChatInfo or not C_ChatInfo.RegisterAddonMessagePrefix then return end
    C_ChatInfo.RegisterAddonMessagePrefix(P.PREFIX)
    self:RegisterEvent("CHAT_MSG_ADDON", "OnAddonMessage")
    self:RegisterEvent("GROUP_ROSTER_UPDATE", "RefreshRoster")
    self:RegisterEvent("PLAYER_ENTERING_WORLD", --[[APR_DIAG]]APRTrace("APR-Core/features/group/PathSharing.lua:343:callback#36", --[[/APR_DIAG]]function() self.rosterSignature = nil; self:RefreshRoster() end--[[APR_DIAG]])--[[/APR_DIAG]])
    self:RegisterEvent("PLAYER_REGEN_ENABLED", "ShowNext")
    self:RefreshRoster()
end--[[APR_DIAG]]; Sharing.OnEnable = APRTrace("APR-Core/features/group/PathSharing.lua:338:Sharing:OnEnable#35", Sharing.OnEnable)--[[/APR_DIAG]]

function Sharing:OnDisable()
    self:UnregisterAllEvents()
    if self.sweep then self.sweep:Cancel(); self.sweep = nil end
    if self.helloTimer then self.helloTimer:Cancel(); self.helloTimer = nil end
    self.peers, self.incoming, self.outgoing, self.prompt, self.rosterSignature = {}, {}, {}, nil, nil
    self.lastOffer, self.helloReplies = {}, {}
    self:CloseDialog()
end--[[APR_DIAG]]; Sharing.OnDisable = APRTrace("APR-Core/features/group/PathSharing.lua:348:Sharing:OnDisable#37", Sharing.OnDisable)--[[/APR_DIAG]]

